const row = $input.first().json || {};
const q = $('Apply Page').first().json.query || {};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const shell = (body) => `<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Apply for a job - Shortlist</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#12213b; --ink-soft:#1d3258; --fog:#f3f5f9; --line:#d3dae6; --steel:#56657e;
    --hl:#ffd93d; --hl-soft:#fff3b8; --danger:#b3261e; --danger-bg:#fdecea;
    --ok:#075e4b; --ok-bg:#d4f0e6;
    --display:'Bricolage Grotesque','Segoe UI',system-ui,sans-serif;
    --body:'Instrument Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--fog);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.5;
    -webkit-font-smoothing:antialiased}
  input,textarea,button{font:inherit;color:inherit}

  .bar{background:#fff;border-bottom:1px solid var(--line)}
  .bar__in{display:flex;align-items:center;height:64px;padding:0 40px}
  .brand{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-weight:700;font-size:20px;letter-spacing:-.02em}
  .brand svg{width:32px;height:32px}

  main{padding:48px 40px 80px}
  h1{margin:0 0 8px;font-family:var(--display);font-size:40px;font-weight:700;line-height:1.1;letter-spacing:-.03em}
  h2{margin:0 0 6px;font-family:var(--display);font-size:22px;font-weight:700;letter-spacing:-.02em}
  .lede{max-width:48rem;margin:0 0 20px;font-size:17px;color:var(--steel)}
  .chips{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:32px}
  .chip{display:inline-block;padding:4px 12px;border-radius:999px;background:var(--hl-soft);color:var(--ink);font-size:13px;font-weight:700}
  .layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:32px;align-items:start}

  .card{background:#fff;border:1px solid var(--line);border-top:4px solid var(--hl);border-radius:12px;padding:32px 36px 36px}
  .card[hidden]{display:none}
  .center{text-align:center;padding:24px 0}
  .okmark{width:44px;height:44px;margin:0 auto 16px;border-radius:50%;background:var(--ok-bg);color:var(--ok);
    display:flex;align-items:center;justify-content:center}
  .okmark svg{width:22px;height:22px}
  .sub{margin:0 0 16px;color:var(--steel)}

  .grid{display:grid;grid-template-columns:1fr 1fr;gap:20px 22px}
  .full{grid-column:1 / -1}
  label.f{display:block;margin:0 0 6px;font-size:14px;font-weight:600}
  input[type=text],input[type=email],input[type=tel],input[type=number]{width:100%;height:48px;padding:0 14px;
    border:1.5px solid var(--line);border-radius:8px;background:#fff;transition:border-color .15s,box-shadow .15s}
  input:hover{border-color:#b3bdcf}
  input:focus-visible{border-color:var(--ink);outline:2px solid transparent;box-shadow:0 0 0 4px var(--hl)}
  ::placeholder{color:#8a96ab}

  .file{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-height:120px;padding:20px;
    border:1.5px dashed #b3bdcf;border-radius:12px;background:#fff;text-align:center;color:var(--steel);cursor:pointer;
    transition:border-color .15s,background-color .15s}
  .file:hover{border-color:var(--ink);background:var(--fog)}
  .file:focus-within{border-color:var(--ink);box-shadow:0 0 0 4px var(--hl)}
  .file strong{font-size:15px;color:var(--ink)}
  .file small{font-size:13px}
  .file.has{border:1.5px solid var(--ok);background:var(--ok-bg);color:var(--ok)}
  .file.has strong{color:var(--ok)}

  .consent{display:flex;gap:12px;align-items:flex-start;margin-top:24px;padding:14px 16px;background:var(--fog);border-radius:8px;
    font-size:14px;color:var(--steel);line-height:1.5;cursor:pointer}
  .consent input{width:18px;height:18px;margin:2px 0 0;flex:none;accent-color:var(--ink);cursor:pointer}

  .errors{margin-top:22px;padding:12px 14px;background:var(--danger-bg);border-left:3px solid var(--danger);border-radius:6px;color:#7a1a14;font-size:15px}
  .errors[hidden]{display:none}
  .errors ul{margin:0;padding-left:20px}
  #go{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;height:50px;margin-top:26px;border:0;border-radius:8px;
    background:var(--ink);color:#fff;font-weight:600;cursor:pointer;transition:background-color .15s}
  #go:hover:not(:disabled){background:var(--ink-soft)}
  #go:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  #go:disabled{opacity:.6;cursor:wait}
  .spin{width:16px;height:16px;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}
  @keyframes spin{to{transform:rotate(360deg)}}

  .side{padding:28px 28px 30px;background:#fff;border:1px solid var(--line);border-radius:12px}
  .steps{margin:16px 0 0;padding:0;list-style:none;counter-reset:s}
  .steps li{position:relative;padding:0 0 18px 40px;counter-increment:s}
  .steps li:last-child{padding-bottom:0}
  .steps li::before{content:counter(s);position:absolute;left:0;top:0;width:28px;height:28px;border-radius:50%;background:var(--ink);color:#fff;
    font-size:14px;font-weight:700;display:flex;align-items:center;justify-content:center}
  .steps li:not(:last-child)::after{content:'';position:absolute;left:13px;top:32px;bottom:4px;width:2px;background:var(--line)}
  .steps b{display:block;font-size:15px}
  .steps span{font-size:14px;color:var(--steel)}
  .ref{display:inline-block;margin:8px 0 18px;padding:10px 18px;background:var(--fog);border:1px solid var(--line);border-radius:8px;
    font-family:var(--display);font-size:20px;font-weight:700;letter-spacing:.02em}
  .hp{position:absolute;left:-9999px;opacity:0}

  @media (max-width:860px){.layout{grid-template-columns:1fr}h1{font-size:32px}}
  @media (max-width:560px){main{padding:32px 16px 56px}.bar__in{padding:0 16px}.card{padding:24px 18px 28px}.grid{grid-template-columns:1fr}}
  @media (prefers-reduced-motion:reduce){*{transition:none!important}.spin{animation-duration:1.8s}}
</style></head>
<body>
<header class="bar"><div class="bar__in">
  <span class="brand">
    <svg viewBox="0 0 32 32" aria-hidden="true">
      <rect width="32" height="32" rx="8" fill="#12213B"/>
      <rect x="9" y="6" width="14" height="20" rx="2" fill="#F7F8FB"/>
      <rect x="11.5" y="10" width="9" height="2" rx="1" fill="#9AA6BA"/>
      <rect x="8" y="14.5" width="16" height="4.5" rx="1" fill="#FFD93D" opacity=".92"/>
      <rect x="11.5" y="15.5" width="9" height="2" rx="1" fill="#12213B"/>
      <rect x="11.5" y="21" width="6" height="2" rx="1" fill="#9AA6BA"/>
    </svg>
    Shortlist
  </span>
</div></header>
${body}
</body></html>`;

if (!row.jobId || row.jobId !== String(q.jobId || '').toUpperCase() || row.status !== 'Open') {
  return [{ json: { html: shell(`<main><div class="card center" style="max-width:640px;margin:0 auto">
    <h1>This position is not available</h1>
    <p class="sub">The job you are looking for is closed or the link is not valid.</p>
  </div></main>`) } }];
}

const chips = [
  Number(row.minExperienceYears) > 0 ? `${esc(row.minExperienceYears)}+ years experience` : '',
  row.education ? esc(row.education) : ''
].filter(Boolean).map(c => `<span class="chip">${c}</span>`).join('');

const jobJson = JSON.stringify(row.jobId).replace(/</g, '\\u003c');

const page = `
<main>
  <div id="main">
    <h1>Apply: ${esc(row.role)}</h1>
    <p class="lede">Fill in your details and upload your CV as a PDF (maximum 5 MB).</p>
    <div class="chips">${chips}</div>

    <div class="layout">
      <section class="card" id="form">
        <div class="grid">
          <div>
            <label class="f" for="name">Full name</label>
            <input type="text" id="name" maxlength="100" autocomplete="name">
          </div>
          <div>
            <label class="f" for="email">Email address</label>
            <input type="email" id="email" maxlength="120" autocomplete="email">
          </div>
          <div>
            <label class="f" for="phone">Phone number</label>
            <input type="tel" id="phone" maxlength="30" autocomplete="tel">
          </div>
          <div>
            <label class="f" for="years">Years of experience</label>
            <input type="number" id="years" min="0" max="50" step="0.5">
          </div>
          <div class="full">
            <label class="f" id="cv-label">CV (PDF only)</label>
            <label class="file" id="drop">
              <input type="file" id="cv" accept="application/pdf,.pdf" hidden aria-labelledby="cv-label">
              <strong id="fname">Click to choose your PDF</strong>
              <small>PDF only, up to 5 MB</small>
            </label>
          </div>
        </div>

        <input type="text" id="website" class="hp" tabindex="-1" autocomplete="off" aria-hidden="true">

        <label class="consent">
          <input type="checkbox" id="consent">
          <span>I agree that my data and CV are processed to evaluate my application.</span>
        </label>

        <div class="errors" id="errors" role="alert" hidden></div>
        <button id="go">Submit application</button>
      </section>

      <aside class="side">
        <h2>What happens next</h2>
        <ol class="steps">
          <li><b>Send your application</b><span>Your details and CV go straight to the hiring team.</span></li>
          <li><b>Keep your reference</b><span>You get a reference ID to use if you need to contact us.</span></li>
          <li><b>Hear back</b><span>Recruiters review applications and contact the candidates they shortlist.</span></li>
        </ol>
      </aside>
    </div>
  </div>
</main>

<script>
var JOB = ${jobJson};
var api = location.pathname.replace(/apply$/, 'apply-submit');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function $(id){ return document.getElementById(id); }
function esc(s){ return String(s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function showErrors(list){
  $('errors').innerHTML = '<ul>' + list.map(function(e){ return '<li>' + esc(e) + '</li>'; }).join('') + '</ul>';
  $('errors').hidden = false;
  $('errors').scrollIntoView({behavior: calm ? 'auto' : 'smooth', block:'center'});
}
$('cv').addEventListener('change', function(){
  var f = this.files[0];
  $('fname').textContent = f ? f.name + ' (' + (f.size / 1048576).toFixed(1) + ' MB)' : 'Click to choose your PDF';
  $('drop').className = f ? 'file has' : 'file';
});
$('go').addEventListener('click', async function(){
  var btn = this;
  $('errors').hidden = true;
  var f = $('cv').files[0], errs = [];
  if (!$('name').value.trim()) errs.push('Please enter your full name.');
  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test($('email').value.trim())) errs.push('Please enter a valid email address.');
  if ($('phone').value.replace(/\\D/g, '').length < 9) errs.push('Please enter a valid phone number.');
  if ($('years').value === '') errs.push('Please enter your years of experience.');
  if (!f) errs.push('Please choose your CV as a PDF file.');
  else if (!/\\.pdf$/i.test(f.name)) errs.push('The CV must be a PDF file.');
  else if (f.size > 5 * 1048576) errs.push('The CV is larger than 5 MB.');
  if (!$('consent').checked) errs.push('You must accept the data processing consent.');
  if (errs.length) { showErrors(errs); return; }

  var fd = new FormData();
  fd.append('jobId', JOB);
  fd.append('name', $('name').value);
  fd.append('email', $('email').value);
  fd.append('phone', $('phone').value);
  fd.append('years', $('years').value);
  fd.append('website', $('website').value);
  fd.append('consent', 'yes');
  fd.append('cv', f);

  btn.disabled = true;
  btn.innerHTML = '<span class="spin" aria-hidden="true"></span>Submitting';
  try {
    var res = await fetch(api, {method: 'POST', body: fd});
    var data = await res.json();
    if (data.ok) {
      $('main').innerHTML = '<div class="card center" style="max-width:640px;margin:0 auto">' +
        '<div class="okmark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div>' +
        '<h1>Application received</h1>' +
        '<p class="sub">Thank you ' + esc(data.name) + '. Your application for <strong>' + esc(data.role) + '</strong> has been received.</p>' +
        '<div class="ref">' + esc(data.applicationId) + '</div>' +
        '<p class="sub">Keep this reference in case you need to contact us.</p></div>';
      return;
    }
    showErrors(data.errors || ['Something went wrong. Please try again.']);
  } catch (e) {
    showErrors(['Could not reach the server. Please try again.']);
  }
  btn.disabled = false; btn.textContent = 'Submit application';
});
</script>`;

return [{ json: { html: shell(page) } }];

const item = $input.first();
const f = item.json.body || {};
const bin = item.binary || {};

const clean = (v, max) => String(v ?? '').trim().slice(0, max);

const jobId = clean(f.jobId, 40).toUpperCase();
const name = clean(f.name, 100).replace(/\s+/g, ' ');
const email = clean(f.email, 120).toLowerCase();
const phoneDigits = clean(f.phone, 30).replace(/\D/g, '');
const years = Number(f.years);
const consented = ['yes', 'true', 'on', '1'].includes(clean(f.consent, 10).toLowerCase());
const honeypot = clean(f.website, 100);

const errors = [];
if (honeypot) errors.push('Your submission could not be processed.');
if (!/^JOB-\d{8}-[A-Z2-9]{4}$/.test(jobId)) errors.push('This application link is not valid. Please use the link from the job post.');
if (name.length < 2) errors.push('Please enter your full name.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('Please enter a valid email address.');
if (phoneDigits.length < 9 || phoneDigits.length > 15) errors.push('Please enter a valid phone number.');
if (!Number.isFinite(years) || years < 0 || years > 50) errors.push('Years of experience must be between 0 and 50.');
if (!consented) errors.push('You must accept the data processing consent.');

const key = Object.keys(bin)[0];
if (!key) {
  errors.push('Please upload your CV as a PDF file.');
} else {
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  if (buf.slice(0, 5).toString('latin1') !== '%PDF-') errors.push('The uploaded file is not a valid PDF.');
  if (buf.length > 5 * 1024 * 1024) errors.push(`The file is too large (${(buf.length / 1048576).toFixed(1)} MB). Maximum is 5 MB.`);
  if (buf.length < 1000) errors.push('The uploaded file looks empty.');
}

const phoneKey = phoneDigits.slice(-10);
const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
let suffix = '';
for (let i = 0; i < 5; i++) suffix += chars[Math.floor(Math.random() * chars.length)];
const applicationId = `APP-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}-${suffix}`;

const out = {
  json: {
    valid: errors.length === 0,
    errors,
    applicationId,
    jobId,
    name,
    email,
    phone: phoneDigits,
    yearsClaimed: Number.isFinite(years) ? years : 0,
    dupKeyEmail: `${jobId}|${email}`,
    dupKeyPhone: `${jobId}|${phoneKey}`,
    consentAt: new Date().toISOString()
  }
};
if (key) out.binary = { Resume: bin[key] };
return [out];

const job = $input.first().json || {};
const open = Boolean(job.jobId) && job.status === 'Open';
return [{ json: { jobOpen: open, jobRole: job.role || '' } }];
